from pathlib import Path
import json,html,re
out=Path('output/quantity-basis-verification')
def load(file):return json.loads((out/file).read_text(encoding='utf8'))
groups=[('หน้าจอ/บันทึก/Frozen','setup-results.json'),('ส่งออกจริง','exports-results.json'),('ราคา/ชุดข้อมูล/Spec','workflows-results.json'),('Backup/Restore','restore-results.json'),('รุ่น build','compiled-results.json')];rows=[]
for group,file in groups:
    data=load(file);assert not data['cloud'] and not data['errors'] and not data['productionRequests']
    for r in data['results']:
        assert r['status']=='PASS';rows.append(f'<tr><td>{html.escape(group)}</td><td>{html.escape(r["name"])}</td><td class="pass">ผ่าน</td></tr>')
